int firstTrue(int n, function<bool(int)> pred) {
    int lo = 0, hi = n;              // search space [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (pred(mid)) hi = mid;
        else lo = mid + 1;
    }
    // lo = first index where pred is true, or n if none
    return lo;
}

int lowerBound(const vector<int>& a, int target) {
    int n = a.size();
    int lo = 0, hi = n;              // search space [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] >= target) hi = mid;
        else lo = mid + 1;
    }
    // lo = first index with a[i] >= target, or n if none
    return lo;
}

int upperBound(const vector<int>& a, int target) {
    int n = a.size();
    int lo = 0, hi = n;              // search space [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] > target) hi = mid;
        else lo = mid + 1;
    }
    // lo = first index with a[i] > target, or n if none
    return lo;
}

