}

long long sumOfMins(const vector<int>& a) {
    int n = a.size();
    vector<int> left(n), right(n), st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] > a[i]) st.pop_back();
        left[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[st.back()] > a[i]) st.pop_back();
        right[i] = st.empty() ? n : st.back();
        st.push_back(i);
    }
    long long total = 0;
    for (int i = 0; i < n; i++)
        total += (long long)a[i] * (i - left[i]) * (right[i] - i);
    return total;
}

int largestRect(vector<int> h) {
    vector<int> st;
    int best = 0;
    for (int i = 0; i < (int)h.size(); i++) {
        while (!st.empty() && h[st.back()] >= h[i]) {
            int height = h[st.back()];
            st.pop_back();
            int left = st.empty() ? -1 : st.back();
            best = max(best, height * (i - left - 1));
        }
        st.push_back(i);
    }
    return best;
}

int trap(const vector<int>& h) {
    vector<int> st;
    int water = 0;
    for (int i = 0; i < (int)h.size(); i++) {
        while (!st.empty() && h[st.back()] < h[i]) {
            int bottom = st.back();
            st.pop_back();
            int left = st.back();
            int width = i - left - 1;
            water += (min(h[left], h[i]) - h[bottom]) * width;
        }
        st.push_back(i);
    }
    return water;
}

struct ListNode { int val; ListNode* next; };
ListNode* removeNth(ListNode* head, int n) {
    ListNode* fast = head;
    for (int i = 0; i < n; i++) fast = fast->next;
    ListNode* slow = head;
    while (fast->next) {
        fast = fast->next;
        slow = slow->next;
    }
    slow->next = slow->next->next;
    return head;
}

struct ListNode { int val; ListNode* next; };
ListNode* middle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

struct ListNode { int val; ListNode* next; };
bool hasCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next && slow != fast) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return fast && fast->next;
}

struct ListNode { int val; ListNode* next; };
ListNode* mergeLists(ListNode* a, ListNode* b) {
    ListNode dummy{0, nullptr};
    ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a;
    return dummy.next;
}

struct ListNode { int val; ListNode* next; };
ListNode* removeAll(ListNode* head, int x) {
    ListNode* cur = head;
    while (cur && cur->next) {
        if (cur->next->val == x) cur->next = cur->next->next;
        else cur = cur->next;
